mkdirSync('dist', { recursive: true })
writeFileSync('dist/theme-toggle.js', themeToggleJs)
writeFileSync('dist/sw-register.js', swRegisterJs)
writeFileSync('dist/sw.js', swJs)
copyDir('public', 'dist')

